chartCss:
:root {
  --ink: #101827;
  --muted: #607086;
  --line: #d9e1ec;
  --paper: #f5f7fb;
  --blue: #2563eb;
  --red: #d43f55;
  --ga-theme-accent: #2563eb;
}
body.ga-friendly-spaces-chart {
  --ga-theme-accent: #8b5a96;
}
body.ga-friendly-spaces-chart .ga-widget {
  padding-bottom: 8px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: transparent;
  color: var(--ink);
  font-family: "Noto Sans TC", "Microsoft JhengHei", Arial, sans-serif;
}
.ga-widget {
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: 18px;
  background:
    radial-gradient(circle at 12% 0%, rgba(37, 99, 235, 0.10), transparent 28%),
    radial-gradient(circle at 92% 12%, rgba(212, 63, 85, 0.12), transparent 30%),
    var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}
.ga-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}
.ga-head-copy {
  min-width: 0;
  flex: 1 1 auto;
  align-self: flex-start;
  margin-top: 10px;
  padding-bottom: 12px;
  position: relative;
}
.ga-head > .ga-metric-switch {
  flex: 0 0 auto;
  align-self: center;
  margin: 32px 18px 0 0;
}
.ga-head-tools {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 10px;
  flex: 0 1 auto;
  flex-wrap: wrap;
  max-width: min(720px, 66%);
}
body.ga-has-metric-switch .ga-head-tools {
  max-width: min(420px, 42%);
}
/* Match solar: title | chips | year on one row (ECOCO has more chips). */
body.ga-has-category-chips .ga-head {
  gap: 12px;
}
body.ga-has-category-chips .ga-head-copy {
  flex: 0 1 auto;
  /* Fit two subtitle lines without stealing space from chips (~OSSD 1058). */
  min-width: min(100%, 19rem);
}
body.ga-has-category-chips .ga-head-tools {
  flex: 1 1 auto;
  flex-wrap: nowrap;
  max-width: none;
  min-width: 0;
  gap: 8px;
}
body.ga-has-category-chips .ga-category-chips {
  flex: 1 1 auto;
  max-width: none;
  min-width: 0;
  justify-content: flex-end;
  gap: 5px;
}
body.ga-has-category-chips .ga-category-chip {
  padding: 6px 10px;
}
body.ga-has-category-chips .ga-controls {
  flex: 0 0 auto;
}
body.ga-has-category-chips .ga-control {
  min-width: 160px;
}
body.ga-has-category-chips .ga-sub,
body.ga-has-category-chips .ga-sub-extra {
  white-space: nowrap;
}
h1 {
  margin: 0 0 6px;
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1.1;
  letter-spacing: 0;
}
.ga-title-row {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.55em;
  margin: 0 0 6px;
}
.ga-title-row h1 {
  margin: 0;
}
.ga-sub {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}
.ga-sub-extra {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}
.ga-sub-extra[hidden] {
  display: none !important;
}
/* Keep title/subtitle flex height identical; park the second line in head-copy padding slack. */
.ga-sub-extra:not([hidden]) {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% - 8px);
}
.ga-location-meta {
  color: #475569;
  font-size: 12.5px;
  font-weight: 850;
  line-height: 1.2;
  white-space: nowrap;
}
.ga-location-meta[hidden] {
  display: none !important;
}
.ga-control {
  min-width: 180px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255,255,255,0.86);
}
.ga-controls {
  display: flex;
  gap: 10px;
  align-items: stretch;
  justify-content: flex-end;
  flex-wrap: wrap;
}
/* Streetlight: campus range chip — hug content; align with year select (not same width). */
.ga-campus-dock {
  position: relative;
  z-index: 35;
  flex: 0 0 auto;
  align-self: flex-end;
  width: auto;
  min-width: 0;
  max-width: min(12.5rem, 100%);
  /* Lift past .ga-control bottom padding so trigger lines up with the year <select>. */
  margin-bottom: 12px;
  /* Clear separation from year (controls gap 10px + 22px → ~32px). */
  margin-inline-end: 22px;
}
.ga-campus-dock[hidden] {
  display: none !important;
}
/* Match .ga-control label row so trigger aligns with the year <select>. */
.ga-campus-dock-align {
  height: 18px;
  margin-bottom: 6px;
}
.ga-campus-dock-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: auto;
  max-width: 100%;
  box-sizing: border-box;
  min-height: 42px;
  padding: 8px 10px;
  border: 1px solid #e8a838;
  border-radius: 8px;
  background:
    linear-gradient(180deg, #fffdf8, #fff6e8);
  color: #9a3412;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 4px 12px rgba(232, 168, 56, 0.18);
  font: inherit;
  font-size: 15px;
  font-weight: 900;
  text-align: left;
  cursor: pointer;
}
.ga-campus-dock-trigger:hover,
.ga-campus-dock.is-open .ga-campus-dock-trigger {
  border-color: #d4921f;
  background: linear-gradient(180deg, #ffffff, #ffefd4);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    0 6px 16px rgba(232, 168, 56, 0.28);
}
.ga-campus-dock-mark {
  flex: 0 0 auto;
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 50%;
  background: rgba(232, 168, 56, 0.22);
  color: #b45309;
}
.ga-campus-dock-mark svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.ga-campus-dock-current {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 950;
  letter-spacing: 0.01em;
}
.ga-campus-dock-caret {
  flex: 0 0 auto;
  color: #b45309;
  font-size: 11px;
  line-height: 1;
  opacity: 0.85;
  transition: transform 140ms ease;
}
.ga-campus-dock:hover .ga-campus-dock-caret,
.ga-campus-dock:focus-within .ga-campus-dock-caret,
.ga-campus-dock.is-open .ga-campus-dock-caret {
  transform: rotate(180deg);
}
.ga-campus-dock-panel {
  position: absolute;
  right: calc(100% + 8px);
  top: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(268px, 70vw);
  padding: 10px;
  border: 1px solid #f0d9a8;
  border-radius: 12px;
  background: #fffdf8;
  box-shadow: 0 22px 46px rgba(120, 70, 10, 0.16);
  opacity: 0;
  visibility: hidden;
  transform: translateX(6px);
  transition: opacity 120ms ease, transform 120ms ease, visibility 120ms ease;
  pointer-events: none;
}
.ga-campus-dock-heading {
  margin: 0;
  color: #9a3412;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1.2;
}
.ga-campus-dock-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}
/* Hover bridge so the panel does not flash-close while moving left. */
.ga-campus-dock-panel::before {
  position: absolute;
  top: 0;
  right: -12px;
  width: 12px;
  height: 100%;
  content: "";
}
.ga-campus-dock:hover .ga-campus-dock-panel,
.ga-campus-dock:focus-within .ga-campus-dock-panel,
.ga-campus-dock.is-open .ga-campus-dock-panel {
  opacity: 1;
  visibility: visible;
  transform: translateX(0);
  pointer-events: auto;
}
/* After a pick: force-hide even if :hover / :focus-within remain. */
.ga-campus-dock.is-closing .ga-campus-dock-panel,
.ga-campus-dock.is-closing:hover .ga-campus-dock-panel,
.ga-campus-dock.is-closing:focus-within .ga-campus-dock-panel,
.ga-campus-dock.is-closing.is-open .ga-campus-dock-panel {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transform: translateX(6px) !important;
}
.ga-campus-dock-choice {
  min-height: 36px;
  padding: 7px 8px;
  border: 1px solid #ead9b8;
  border-radius: 8px;
  background: #fff;
  color: #334155;
  font: inherit;
  font-size: 13px;
  font-weight: 850;
  cursor: pointer;
}
.ga-campus-dock-choice:hover {
  border-color: #e8a838;
  background: #fff8eb;
}
.ga-campus-dock-choice.is-active {
  border-color: #e8a838;
  background: #fff8eb;
  color: #9a3412;
  font-weight: 950;
  box-shadow: inset 3px 0 0 #e8a838;
}
.ga-control[hidden] {
  display: none;
}
.ga-control label {
  display: block;
  margin-bottom: 6px;
  color: #334155;
  font-size: 12px;
  font-weight: 900;
}
.ga-category-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  justify-content: flex-end;
  max-width: min(560px, 100%);
  margin: 0;
  padding: 0 0 2px;
}
.ga-category-chips[hidden] {
  display: none !important;
}
.ga-category-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #d5dee9;
  border-radius: 999px;
  padding: 7px 12px;
  background: #fff;
  color: #64748b;
  font-size: 13px;
  font-weight: 850;
  line-height: 1.1;
  cursor: pointer;
  transition: border-color 140ms ease, color 140ms ease, background 140ms ease, box-shadow 140ms ease;
}
.ga-category-chip.is-parent {
  font-weight: 950;
}
.ga-category-chip.is-active {
  color: #fff;
  border-color: transparent;
}
select {
  width: 100%;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 9px 10px;
  background: #fff;
  color: var(--ink);
  font-size: 15px;
  font-weight: 900;
}
.ga-grid {
  display: grid;
  grid-template-columns: minmax(300px, 0.92fr) minmax(0, 1.45fr);
  gap: 14px;
}
.ga-card {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255,255,255,0.94);
  box-shadow: 0 18px 40px rgba(15, 23, 42, 0.08);
}
.ga-pr-card { padding: 18px; }
.ga-rank-block { min-width: 0; }
.ga-card-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}
.ga-card-title h2 {
  margin: 0;
  font-size: 18px;
  line-height: 1.2;
}
.ga-coverage-wrap {
  position: relative;
  flex: 0 0 auto;
}
.ga-coverage-wrap::after {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  height: 14px;
  content: "";
}
.ga-coverage {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 6px 10px 6px 12px;
  border: 1px solid #93c5fd;
  border-radius: 999px;
  background: #eef6ff;
  color: #1d4ed8;
  font-family: inherit;
  font-size: 12px;
  font-weight: 950;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(29, 78, 216, 0.12);
  transition: border-color 140ms ease, background 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}
.ga-coverage[hidden] {
  display: none !important;
}
.ga-coverage:hover,
.ga-coverage[aria-expanded="true"] {
  border-color: #60a5fa;
 background: #dbeafe;
  box-shadow: 0 4px 12px rgba(29, 78, 216, 0.16);
}
.ga-coverage:active {
  transform: translateY(1px);
}
.ga-coverage-caret {
  display: inline-block;
  font-size: 10px;
  line-height: 1;
  opacity: 0.85;
  transform: translateY(-0.5px);
  transition: transform 0.15s ease;
}
.ga-coverage[aria-expanded="true"] .ga-coverage-caret {
  transform: translateY(-0.5px) rotate(180deg);
}
.ga-coverage.ga-formula {
  align-items: flex-start;
  justify-content: flex-start;
  flex-direction: column;
  gap: 5px;
  max-width: 330px;
  padding: 8px 10px;
  border-color: #d9e1ec;
  border-radius: 12px;
  background: #f8fafc;
  color: #334155;
  line-height: 1.35;
  text-align: left;
  white-space: normal;
  cursor: default;
}
.ga-coverage.ga-formula:hover,
.ga-coverage.ga-formula[aria-expanded="true"] {
  border-color: #d9e1ec;
  background: #f8fafc;
}
.ga-formula-line {
  display: block;
  color: #101827;
  font-size: 12px;
  font-weight: 950;
}
.ga-formula-math {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #101827;
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.15;
  white-space: nowrap;
}
.ga-fraction {
  display: inline-grid;
  grid-template-rows: auto auto;
  align-items: center;
  min-width: 102px;
  text-align: center;
}
.ga-frac-top {
  display: block;
  padding: 0 8px 4px;
  border-bottom: 2px solid #111827;
}
.ga-frac-bottom {
  display: block;
  padding: 4px 8px 0;
}
.ga-formula-times {
  font-size: 13.5px;
  font-weight: 500;
}
.ga-month-popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 30;
  width: 252px;
  padding: 12px;
  border: 1px solid #dbe4ef;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.16);
}
.ga-month-popover[hidden] {
  display: none;
}
.ga-month-popover.is-month-pick {
  width: 268px;
}
.ga-metric-popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 30;
  width: 168px;
  padding: 12px;
  border: 1px solid #dbe4ef;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.16);
}
.ga-metric-popover[hidden] {
  display: none;
}
.ga-metric-options {
  display: grid;
  gap: 6px;
}
.ga-metric-options button {
  border: 1px solid #dbe4ef;
  border-radius: 8px;
  padding: 8px 10px;
  background: #f8fafc;
  color: #334155;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 950;
  text-align: left;
  cursor: pointer;
}
.ga-metric-options button:hover {
  border-color: #93c5fd;
  background: #eef6ff;
  color: #1d4ed8;
}
.ga-metric-options button.active {
  border-color: #1f4b99;
  background: #1f4b99;
  color: #ffffff;
}
.ga-month-title {
  margin-bottom: 9px;
  color: #101827;
  font-size: 13px;
  font-weight: 950;
}
.ga-month-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.ga-month-fields[hidden],
.ga-month-actions[hidden],
.ga-month-grid[hidden] {
  display: none !important;
}
.ga-month-fields label {
  color: #475569;
  font-size: 11px;
  font-weight: 900;
}
.ga-month-fields select {
  margin-top: 4px;
  padding: 6px 18px 6px 6px;
  font-size: 11px;
  font-weight: 800;
  text-align: left;
  text-align-last: left;
}
.ga-month-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}
.ga-month-grid button {
  border: 1px solid #dbe4ef;
  border-radius: 8px;
  padding: 8px 0;
  background: #f8fafc;
  color: #334155;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 950;
  cursor: pointer;
}
.ga-month-grid button:hover:not(:disabled) {
  border-color: #93c5fd;
  background: #eef6ff;
  color: #1d4ed8;
}
.ga-month-grid button.active {
  border-color: #1f4b99;
  background: #1f4b99;
  color: #ffffff;
}
.ga-month-grid button:disabled {
  opacity: 0.34;
  cursor: not-allowed;
}
.ga-month-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
}
.ga-month-actions button {
  border: 0;
  border-radius: 999px;
  padding: 7px 11px;
  font-family: inherit;
  font-size: 12px;
  font-weight: 950;
  cursor: pointer;
}
.ga-month-reset {
  background: #edf2f7;
  color: #475569;
}
.ga-month-apply {
  background: #101827;
  color: #ffffff;
}
.ga-pr-score {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 10px;
  margin: 4px 0 12px;
  transform: translateX(-8%);
}
.ga-pr-score strong {
  font-size: clamp(54px, 8vw, 86px);
  line-height: 0.9;
  font-weight: 950;
}
.ga-pr-score span {
  margin-bottom: 8px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 900;
}
.ga-replacement-chart .ga-pr-card {
  overflow: visible;
}
.ga-replacement-chart .ga-card-title {
  align-items: flex-start;
}
.ga-replacement-chart .ga-card-title h2 {
  min-width: 0;
}
.ga-replacement-chart .ga-coverage-wrap {
  max-width: none;
  flex: 0 1 auto;
  min-width: 0;
  margin-right: 10px;
}
.ga-replacement-chart .ga-coverage:not(.ga-formula) {
  max-width: none;
  white-space: nowrap;
}
.ga-replacement-chart .ga-coverage.ga-formula {
  max-width: 100%;
  padding: 7px 9px;
}
.ga-replacement-chart .ga-pr-score {
  justify-content: flex-start;
  align-items: flex-end;
  gap: 8px;
  min-width: 0;
  margin: 10px 0 12px;
  transform: none;
}
.ga-replacement-chart .ga-pr-score strong {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 76%;
  font-size: clamp(44px, 5vw, 66px);
  letter-spacing: -0.025em;
  line-height: 0.92;
  white-space: nowrap;
}
.ga-replacement-chart .ga-pr-score span {
  flex: 0 0 auto;
  min-width: 58px;
  margin-bottom: 4px;
  color: #64748b;
  font-size: clamp(9px, 0.82vw, 11px);
  line-height: 1.15;
  font-weight: 950;
  white-space: nowrap;
}
.ga-value-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 14px 0;
}
.ga-mini {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 11px 12px;
  background: #f8fafc;
}
.ga-mini-label {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}
.ga-mini-value {
  margin-top: 4px;
  font-size: 22px;
  font-weight: 950;
  white-space: nowrap;
  overflow: hidden;
}
.ga-replacement-chart .ga-mini {
  padding: 10px 11px;
}
.ga-replacement-chart .ga-mini-label {
  font-size: 11.5px;
}
.ga-replacement-chart .ga-mini-value {
  font-size: clamp(19px, 2.15vw, 22px);
}
.ga-value-number,
.ga-value-unit {
  display: inline-block;
  vertical-align: baseline;
}
.ga-value-unit {
  margin-left: 4px;
  font-size: 0.76em;
  line-height: 1;
}
.ga-pr-track {
  position: relative;
  height: 32px;
  margin: 18px 0 9px;
  border-radius: 999px;
  background: #e9eef6;
  overflow: hidden;
}
.ga-pr-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, #2563eb 0%, #b8c7d9 52%, #d43f55 100%) left center / 100% 100% no-repeat;
  transition: width 260ms ease;
}
.ga-pr-pin {
  position: absolute;
  top: -5px;
  left: 0%;
  width: 4px;
  height: 42px;
  border-radius: 999px;
  background: #111827;
  box-shadow: 0 0 0 4px rgba(255,255,255,0.78);
  transform: translateX(-2px);
  transition: left 260ms ease;
}
.ga-axis {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
}
.ga-hint {
  margin-top: 12px;
  color: #475569;
  font-size: 12px;
  line-height: 1.45;
}
.ga-replacement-chart .ga-hint {
  white-space: nowrap;
  font-size: clamp(10px, 0.85vw, 12px);
  line-height: 1.35;
  letter-spacing: -0.01em;
  color: #64748b;
}
.ga-replacement-chart .ga-pr-track,
.ga-replacement-chart .ga-axis,
