explorerCss:
:root {
  --ink: #172033;
  --muted: #667085;
  --line: #dbe2eb;
  --paper: #f5f7fa;
  --navy: #203754;
  --blue: #4567e8;
  color-scheme: light;
}

* { box-sizing: border-box; }

html,
body {
  margin: 0;
  min-width: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: Inter, "Noto Sans TC", "Microsoft JhengHei", sans-serif;
  letter-spacing: 0;
}

body { overflow-x: hidden; }
[hidden] { display: none !important; }

.oga-portal {
  width: min(1280px, 100%);
  margin: 0 auto;
  padding: 22px 24px 2px;
}

.oga-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding: 6px 4px 20px;
}

.oga-brand {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.oga-brand-mark {
  display: grid;
  flex: 0 0 48px;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid #c9d5e4;
  border-radius: 8px;
  background: var(--navy);
  color: #fff;
  box-shadow: 0 8px 22px rgba(32, 55, 84, 0.16);
}

.oga-brand-mark svg { width: 25px; height: 25px; }
.oga-eyebrow {
  display: block;
  margin-bottom: 4px;
  color: var(--navy);
  font-size: 13.5px;
  font-weight: 800;
  letter-spacing: 0.04em;
}
.oga-brand h1 { margin: 0; font-size: clamp(24px, 3vw, 34px); line-height: 1.12; }
.oga-brand p { margin: 6px 0 0; color: var(--muted); font-size: 13px; line-height: 1.5; }



.oga-chart-nav {
  position: relative;
  z-index: 40;
  display: flex;
  justify-content: center;
  gap: 12px;
  padding: 8px 4px 4px;
}

.oga-nav-dismiss {
  position: fixed;
  inset: 0;
  z-index: 30;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: default;
}

.oga-nav-dismiss[hidden] {
  display: none !important;
}

.oga-nav-group {
  position: relative;
  flex: 1 1 220px;
  min-width: min(100%, 180px);
  max-width: 320px;
}

.oga-nav-group::after {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  height: 16px;
  content: "";
}

.oga-nav-group-trigger {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  width: 100%;
  min-height: 64px;
  padding: 10px 13px 11px;
  border: 1px solid var(--nav-border, #d8e1ec);
  border-radius: 10px;
  background:
    radial-gradient(circle at 14% 0%, var(--nav-glow-a, rgba(37, 99, 235, 0.10)), transparent 42%),
    radial-gradient(circle at 108% 0%, var(--nav-glow-b, rgba(212, 63, 85, 0.08)), transparent 44%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), var(--nav-bg, #f7f9fc));
  color: var(--nav-ink, var(--ink));
  font: inherit;
  text-align: left;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.96),
    0 10px 24px rgba(23, 32, 51, 0.08);
  overflow: hidden;
  transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease, background 140ms ease;
}


.oga-nav-group-trigger::after {
  position: absolute;
  inset: 1px 1px auto 1px;
  height: 42%;
  border-radius: 9px 9px 0 0;
  background: linear-gradient(180deg, rgba(255,255,255,0.58), rgba(255,255,255,0));
  content: "";
  pointer-events: none;
}

.oga-nav-group-trigger:hover,
