    radial-gradient(circle at 14% 0%, var(--nav-glow-active-a, var(--nav-glow-a)), transparent 42%),
    radial-gradient(circle at 108% 0%, var(--nav-glow-active-b, var(--nav-glow-b)), transparent 44%),
