}

.oga-nav-group-trigger > svg:first-child {
  width: 34px;
  height: 34px;
  padding: 7px;
  border: 1px solid color-mix(in srgb, var(--nav-accent, var(--blue)) 22%, white);
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.86), rgba(255,255,255,0.42)),
    var(--nav-icon-bg, #eef4ff);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.88), 0 7px 16px rgba(23, 32, 51, 0.08);
