.oga-nav-choice .oga-custom-icon svg {
  width: 18px;
  height: 18px;
  color: var(--nav-accent, #697789);
  fill: none;
  stroke: currentColor;
  stroke-width: 2.15;
  stroke-linecap: round;
  stroke-linejoin: round;
}


.oga-nav-group-trigger svg:last-child {
  width: 16px;
  height: 16px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: color-mix(in srgb, var(--nav-accent, var(--blue)) 74%, #344054);
  transition: transform 140ms ease;
}

.oga-nav-group:hover .oga-nav-group-trigger svg:last-child,
.oga-nav-group:focus-within .oga-nav-group-trigger svg:last-child,
.oga-nav-group.is-open .oga-nav-group-trigger svg:last-child {
  transform: rotate(180deg);
}

.oga-nav-group-trigger span {
  position: relative;
  z-index: 1;
  min-width: 0;
  font-size: 15px;
  font-weight: 950;
  line-height: 1.18;
  white-space: nowrap;
}

.oga-nav-group-trigger small {
  display: block;
  margin-bottom: 4px;
  color: var(--nav-muted, #718096);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.oga-nav-menu {
  position: absolute;
  top: calc(100% + 5px);
  left: 0;
  z-index: 40;
  /* Match theme card width so the rightmost menu is not clipped past the portal. */
  width: 100%;
  box-sizing: border-box;
  padding: 8px;
  border: 1px solid var(--nav-border, #dce3ed);
  border-radius: 10px;
  background:
    radial-gradient(circle at 12% 0%, var(--nav-glow-a, rgba(37, 99, 235, 0.08)), transparent 38%),
    rgba(255, 255, 255, 0.98);
  box-shadow: 0 22px 46px rgba(15, 23, 42, 0.17);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity 120ms ease, transform 120ms ease, visibility 120ms ease;
}

.oga-nav-group:hover .oga-nav-menu,
.oga-nav-group:focus-within .oga-nav-menu,
.oga-nav-group.is-open .oga-nav-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.oga-nav-menu::before {
  position: absolute;
  top: -7px;
  left: 26px;
  width: 12px;
  height: 12px;
  border-top: 1px solid var(--nav-border, #dce3ed);
  border-left: 1px solid var(--nav-border, #dce3ed);
  background: #fff;
  transform: rotate(45deg);
  content: "";
}

.oga-nav-choice {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #2f3a4c;
  font: inherit;
  font-size: 14px;
  font-weight: 900;
  text-align: left;
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease, transform 120ms ease;
}

.oga-nav-choice > span:not(.oga-custom-icon):not(.oga-nav-soon) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.oga-nav-choice svg {
  width: 18px;
  height: 18px;
  color: var(--nav-accent, #697789);
}

.oga-nav-choice:hover {
  background: rgba(15, 23, 42, 0.04);
}

.oga-nav-choice.is-active {
  background: rgba(15, 23, 42, 0.06);
  color: var(--nav-ink, #172033);
}

.oga-nav-choice.is-active svg {
  color: var(--nav-accent, #203754);
}

.oga-nav-choice.is-soon,
.oga-mobile-theme-choice.is-soon {
  cursor: not-allowed;
  opacity: 0.68;
}

.oga-nav-choice.is-soon svg {
  flex-shrink: 0;
  color: var(--nav-muted, #667085);
}

.oga-nav-choice.is-soon:hover,
.oga-mobile-theme-choice.is-soon:hover {
  background: transparent;
  transform: none;
}

.oga-nav-soon {
  flex-shrink: 0;
  margin-left: auto;
  padding-left: 8px;
  color: var(--nav-muted, #667085);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.oga-mobile-select { display: none; }

.oga-open-label--mobile { display: none; }

.oga-mobile-theme-nav {
  display: none;
}

.oga-stage {
  margin-top: 16px;
}

.oga-stage-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 42px;
  padding: 0 4px 10px;
}

.oga-stage-current {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.oga-stage-label { color: var(--muted); font-size: 11px; font-weight: 800; }
.oga-stage-bar strong { font-size: 15px; }

.oga-open-nudge {
  display: none;
  flex: 0 1 auto;
  align-items: center;
  min-width: 0;
  max-width: min(100%, 24rem);
  margin: 0 0 0 auto;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--navy);
  font-size: 12.5px;
  font-weight: 800;
  line-height: 1.3;
  text-align: right;
  pointer-events: none;
  user-select: none;
}
.oga-open-nudge[hidden] { display: none !important; }
.oga-stage-bar--nudge .oga-open-nudge:not([hidden]) {
  display: inline-flex;
}
.oga-stage-bar--nudge {
  justify-content: flex-start;
  gap: 8px;
}
.oga-stage-bar--nudge a {
  margin-left: 0;
}
.oga-open-nudge span {
  min-width: 0;
}
.oga-stage-bar a {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 7px 12px;
  border: 1px solid var(--blue);
  border-radius: 999px;
  background: var(--blue);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
  text-decoration: none;
  box-shadow: 0 1px 2px rgba(32, 55, 84, 0.18);
  transition: background 120ms ease, border-color 120ms ease, box-shadow 120ms ease, transform 120ms ease;
}
.oga-stage-bar a:hover {
  background: color-mix(in srgb, var(--blue) 82%, #0f1b33);
  border-color: color-mix(in srgb, var(--blue) 82%, #0f1b33);
  color: #fff;
  box-shadow: 0 2px 6px rgba(32, 55, 84, 0.22);
  transform: translateY(-1px);
}
.oga-stage-bar a:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--blue) 45%, white);
  outline-offset: 2px;
}
.oga-stage-bar a:active {
  transform: translateY(0);
  box-shadow: 0 1px 2px rgba(32, 55, 84, 0.16);
}
.oga-stage-bar a svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: #fff;
  stroke: #fff;
}

.oga-frame-wrap {
  position: relative;
  min-height: 360px;
  overflow: hidden;
}

#chartFrame {
  display: block;
  width: 100%;
  min-height: 360px;
  border: 0;
  background: transparent;
  opacity: 1;
  overflow: hidden;
}

.oga-stage[aria-busy="true"] #chartFrame { opacity: 0; visibility: hidden; }

.oga-loading {
  position: absolute;
  z-index: 2;
  inset: 110px 0 auto;
  display: grid;
  place-items: center;
  gap: 10px;
  color: #52637a;
  font-size: 12px;
  pointer-events: none;
}

.oga-loading-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: #fff;
  color: var(--blue);
  box-shadow: 0 8px 22px rgba(23, 32, 51, 0.08);
}
.oga-loading-mark svg { width: 19px; height: 19px; animation: oga-spin 900ms linear infinite; }


.oga-footnote {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px 16px;
  margin-top: 0;
  padding: 0 4px;
  border-top: none;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.15;
}

.oga-footnote p {
  margin: 0;
  min-width: 0;
}

#sourceInfo {
  flex: 0 1 auto;
  color: #52637a;
  font-weight: 700;
  white-space: nowrap;
}

.oga-footnote-note {
  flex: 1 1 auto;
  text-align: right;
  font-weight: 500;
  color: var(--muted);
}

/* Embedded mode: opaque background prevents host-page decorations bleeding through,
   and overflow:hidden avoids a nested scrollbar while the parent iframe auto-grows. */
html.is-embedded,
html.is-embedded body {
  height: auto !important;
  min-height: 0 !important;
  overflow: hidden !important;
  background: var(--paper) !important;
}

html.is-embedded .oga-portal {
  padding: 8px 14px 0;
  background: var(--paper);
  min-height: 0;
}

/* Compact nest must not restore a tall portal bottom under the footnote. */
html.is-embedded.is-layout-compact .oga-portal {
  padding: 8px 12px 0;
}

html.is-layout-compact .oga-footnote {
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
}

html.is-layout-compact .oga-footnote-note {
  text-align: left;
}

html.is-layout-compact #sourceInfo {
  white-space: normal;
}

html.is-embedded .oga-header {
  padding: 0 4px 8px;
  gap: 12px;
}

html.is-embedded .oga-brand h1 {
  font-size: clamp(22px, 2.6vw, 28px);
  line-height: 1.1;
}

html.is-embedded .oga-brand p {
  margin-top: 2px;
  max-width: 36rem;
  font-size: 12px;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

html.is-embedded .oga-chart-nav {
  gap: 8px;
  padding: 2px 4px 0;
}

html.is-embedded .oga-nav-group-trigger {
  min-height: 52px;
  padding: 8px 11px 9px;
  gap: 9px;
}

/* C1a/C1c: embed desktop nav — fit 4 themes at Wix ~1058 without compact switch.
   Keep .oga-nav-group overflow visible so .oga-nav-menu dropdowns are not clipped. */
html.is-embedded:not(.is-layout-compact) .oga-portal {
  padding-inline: 9px;
}

html.is-embedded:not(.is-layout-compact) .oga-chart-nav {
  gap: 1px;
  padding-inline: 0;
  overflow: visible;
}

html.is-embedded:not(.is-layout-compact) .oga-nav-group {
  flex: 1 1 0;
  min-width: 0;
  max-width: none;
  overflow: visible;
}

html.is-embedded:not(.is-layout-compact) .oga-nav-group-trigger {
  min-height: 50px;
  padding: 7px 5px 8px;
  gap: 3px;
}

html.is-embedded:not(.is-layout-compact) .oga-nav-group-trigger span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 13px;
}

html.is-embedded:not(.is-layout-compact) .oga-nav-group-trigger small {
  font-size: 9px;
  margin-bottom: 2px;
  letter-spacing: 0.04em;
}

html.is-embedded:not(.is-layout-compact) .oga-nav-group-trigger > svg:first-child {
  width: 28px;
  height: 28px;
  padding: 5px;
}

html.is-embedded:not(.is-layout-compact) .oga-nav-group-trigger svg:last-child {
  width: 14px;
  height: 14px;
}

html.is-embedded .oga-stage {
  margin-top: 8px;
}

html.is-embedded .oga-stage-bar {
  min-height: 34px;
  padding: 0 4px 6px;
}

html.is-embedded .oga-stage-bar a {
  min-height: 32px;
  padding: 6px 11px;
  font-size: 12px;
}

html.is-embedded.is-layout-compact .oga-stage-bar a {
  min-height: 44px;
  padding: 10px 16px;
  font-size: 13.5px;
}

html.is-embedded .oga-frame-wrap,
html.is-embedded #chartFrame {
  min-height: 0 !important;
}

html.is-embedded .oga-footnote {
  margin-top: 0;
  padding: 0 4px;
  gap: 8px 12px;
  font-size: 10px;
  line-height: 1.15;
}

html.is-embedded .oga-footnote-note {
  font-size: 9.5px;
}

/* Embed content layout (?embed=1&layout=content): chrome-free shell for host iframes.
   Independent of is-layout-compact (responsive). Must not alter plain ?embed=1. */
.oga-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.oga-open-label--content {
  display: none;
}

html.is-embedded.is-layout-content .oga-portal {
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 4px 8px 0;
}

html.is-embedded.is-layout-content .oga-header {
  display: none;
}

html.is-embedded.is-layout-content .oga-chart-nav {
  padding-top: 0;
}

html.is-embedded.is-layout-content .oga-stage {
  margin-top: 4px;
}

html.is-embedded.is-layout-content .oga-open-label--desktop,
html.is-embedded.is-layout-content .oga-open-label--mobile {
  display: none;
}

html.is-embedded.is-layout-content .oga-open-label--content {
  display: inline;
}

html.is-embedded.is-layout-content .oga-open-nudge {
  display: none !important;
}

html.is-embedded.is-layout-content .oga-stage-bar {
  justify-content: space-between;
  gap: 8px;
}

html.is-embedded.is-layout-content .oga-stage-bar a {
  font-size: 12px;
  padding: 5px 10px;
  min-height: 28px;
  font-weight: 700;
  opacity: 0.92;
}

html.is-embedded.is-layout-content .oga-stage-bar a:hover,
html.is-embedded.is-layout-content .oga-stage-bar a:focus-visible {
  opacity: 1;
}

@keyframes oga-spin { to { transform: rotate(360deg); } }

@media (max-width: 1040px) {
  .oga-chart-nav { gap: 10px; }
  .oga-nav-group {
    flex: 1 1 180px;
    min-width: min(100%, 160px);
  }
  .oga-nav-group-trigger { padding-inline: 10px; }
}

/* Phase 3A: compact layout driven by html.is-layout-compact (set from compactMaxWidth via JS). */
html.is-layout-compact {
  .oga-portal { padding: 14px 12px 14px; }
  .oga-header { align-items: flex-start; padding: 4px 0 10px; }
  .oga-brand-mark { flex-basis: 36px; width: 36px; height: 36px; }
  .oga-brand h1 { font-size: 22px; line-height: 1.1; }
  .oga-brand p {
    max-width: 32rem;
    margin-top: 2px;
    font-size: 11px;
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .oga-eyebrow, .oga-chart-nav { display: none; }
  .oga-mobile-select { display: none; }
  .oga-open-label--desktop { display: none; }
  .oga-open-label--mobile { display: inline; }

  .oga-mobile-theme-nav {
    display: grid;
    gap: 8px;
    margin: 0 0 2px;
  }
  .oga-mobile-theme-toolbar {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 6px;
  }
  .oga-mobile-theme-status {
    margin: 0;
    text-align: center;
    color: #52637a;
    font-size: 11px;
    font-weight: 900;
  }
  .oga-mobile-theme-arrow {
    display: grid;
    width: 36px;
    height: 36px;
    place-items: center;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: #fff;
    color: var(--ink);
    cursor: pointer;
  }
  .oga-mobile-theme-arrow svg { width: 18px; height: 18px; }
  .oga-mobile-theme-viewport {
    min-width: 0;
  }
  .oga-mobile-theme-panel {
    min-width: 0;
  }
  .oga-mobile-theme-panel[data-group="circularity"] {
    --nav-bg: #f7fbf9;
    --nav-bg-active: #edf8f3;
    --nav-border: #d3e8df;
    --nav-border-active: #a9d8c7;
    --nav-ink: #183f39;
    --nav-muted: #638278;
    --nav-accent: #16806e;
    --nav-icon-bg: #e5f5ee;
    --nav-glow-a: rgba(22, 128, 110, 0.15);
    --nav-glow-b: rgba(207, 69, 87, 0.08);
    --nav-shadow: rgba(22, 128, 110, 0.18);
  }
  .oga-mobile-theme-panel[data-group="energy-water"] {
    --nav-bg: #f6f9ff;
    --nav-bg-active: #edf4ff;
    --nav-border: #d1dff2;
    --nav-border-active: #aec7e8;
    --nav-ink: #203754;
    --nav-muted: #65768d;
    --nav-accent: #356cc9;
    --nav-icon-bg: #e8f1ff;
    --nav-glow-a: rgba(53, 108, 201, 0.16);
    --nav-glow-b: rgba(212, 154, 36, 0.13);
    --nav-shadow: rgba(53, 108, 201, 0.18);
  }
  .oga-mobile-theme-panel[data-group="replacement"] {
    --nav-bg: #fbf8f5;
    --nav-bg-active: #f6efe8;
    --nav-border: #e5d8cb;
    --nav-border-active: #d2bea7;
    --nav-ink: #41384a;
    --nav-muted: #81717e;
    --nav-accent: #b46a2a;
    --nav-icon-bg: #f4eadf;
    --nav-glow-a: rgba(180, 106, 42, 0.15);
    --nav-glow-b: rgba(93, 88, 120, 0.12);
    --nav-shadow: rgba(180, 106, 42, 0.17);
  }
  .oga-mobile-theme-panel[data-group="friendly-spaces"] {
    --nav-bg: #faf7fb;
    --nav-bg-active: #f3edf8;
    --nav-border: #e5d9eb;
    --nav-border-active: #cdb8d4;
    --nav-ink: #3d2f42;
    --nav-muted: #7a687f;
    --nav-accent: #8b5a96;
    --nav-icon-bg: #f0e8f4;
    --nav-glow-a: rgba(139, 90, 150, 0.15);
    --nav-glow-b: rgba(212, 120, 140, 0.10);
    --nav-shadow: rgba(139, 90, 150, 0.16);
  }
  .oga-mobile-theme-card {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    width: 100%;
    min-height: 58px;
    padding: 10px 12px;
    border: 1px solid var(--nav-border, #d8e1ec);
    border-radius: 12px;
    background:
      radial-gradient(circle at 14% 0%, var(--nav-glow-a, rgba(37, 99, 235, 0.10)), transparent 42%),
      radial-gradient(circle at 108% 0%, var(--nav-glow-b, rgba(212, 63, 85, 0.08)), transparent 44%),
      linear-gradient(180deg, rgba(255, 255, 255, 0.98), var(--nav-bg, #f7f9fc));
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.96),
      0 10px 24px var(--nav-shadow, rgba(15, 23, 42, 0.06));
    color: var(--nav-ink, var(--ink));
    text-align: left;
    cursor: pointer;
    font: inherit;
  }
  .oga-mobile-theme-panel.is-active .oga-mobile-theme-card {
    border-color: var(--nav-border-active, #c7d4e4);
    background:
      radial-gradient(circle at 14% 0%, var(--nav-glow-a, rgba(37, 99, 235, 0.16)), transparent 42%),
      radial-gradient(circle at 108% 0%, var(--nav-glow-b, rgba(212, 63, 85, 0.10)), transparent 44%),
      linear-gradient(180deg, #ffffff, var(--nav-bg-active, #edf3fa));
  }
  .oga-mobile-theme-card > i,
  .oga-mobile-theme-card > .oga-custom-icon {
    display: grid;
    width: 28px;
    height: 28px;
    place-items: center;
    border-radius: 8px;
    background: var(--nav-icon-bg, #eef2ff);
    color: var(--nav-accent, var(--navy));
  }
  .oga-mobile-theme-card > i svg,
  .oga-mobile-theme-card > .oga-custom-icon svg {
    width: 18px;
    height: 18px;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    fill: none;
    stroke: currentColor;
    stroke-width: 2.35;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  .oga-mobile-theme-card > .oga-custom-icon.oga-circularity-icon svg circle {
    fill: color-mix(in srgb, var(--nav-accent, #16806e) 16%, white);
    stroke-width: 1.75;
  }
  .oga-mobile-theme-copy {
    display: grid;
    gap: 1px;
    min-width: 0;
  }
  .oga-mobile-theme-copy small {
    color: var(--nav-muted, #667085);
    font-size: 10px;
    font-weight: 800;
  }
  .oga-mobile-theme-copy strong {
    font-size: 15px;
    font-weight: 900;
    line-height: 1.2;
    color: var(--nav-ink, var(--ink));
  }
  .oga-mobile-theme-current {
    color: var(--nav-accent, #4567e8);
    font-size: 11px;
    font-style: normal;
    font-weight: 800;
  }
  .oga-mobile-theme-card > i:last-child {
    width: 18px;
    height: 18px;
    background: transparent;
    color: var(--nav-muted, #667085);
  }
  .oga-mobile-theme-choices {
    display: grid;
    gap: 8px;
    margin-top: 8px;
    padding: 10px;
    border: 1px solid var(--nav-border, var(--line));
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.96);
  }
  .oga-mobile-theme-choice {
    min-height: 44px;
    padding: 10px 12px;
    border: 1px solid #dbe2eb;
    border-radius: 10px;
    background: #f8fafc;
    color: var(--ink);
    font: inherit;
    font-weight: 800;
    text-align: left;
    cursor: pointer;
  }
  .oga-mobile-theme-choice.is-active {
    border-color: var(--nav-border-active, #93c5fd);
    background: var(--nav-icon-bg, #eef6ff);
    color: var(--nav-accent, #1d4ed8);
  }
  .oga-mobile-theme-choice.is-soon {
    cursor: not-allowed;
    opacity: 0.62;
    background: #f1f5f9;
    color: var(--nav-muted, #667085);
  }
  .oga-mobile-theme-dots {
    display: flex;
    justify-content: center;
    gap: 8px;
  }
  .oga-mobile-theme-dots button {
    width: 8px;
    height: 8px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: #cbd5e1;
    cursor: pointer;
  }
  .oga-mobile-theme-dots button.is-active {
    background: var(--navy);
  }

  .oga-stage { margin-top: 6px; }
  .oga-stage-bar {
    min-height: 44px;
    padding: 0 0 8px;
    justify-content: flex-end;
    gap: 8px;
  }
  .oga-stage-bar--nudge {
    justify-content: flex-start;
    gap: 8px;
  }
  .oga-stage-current { display: none; }
  .oga-stage-label { display: none; }
  .oga-stage-bar strong { font-size: 14px; }

  /* Mobile: stronger open cue — same blue family, larger hit target + clearer nudge. */
  .oga-open-nudge {
    max-width: min(100%, 12.5rem);
    padding: 6px 8px;
    border-radius: 8px;
    background: color-mix(in srgb, var(--blue) 10%, white);
    color: color-mix(in srgb, var(--navy) 88%, var(--blue));
    font-size: 13.5px;
    font-weight: 900;
    line-height: 1.25;
    text-align: left;
  }
  .oga-stage-bar a {
    min-height: 44px;
    padding: 10px 16px;
    border-color: color-mix(in srgb, var(--blue) 78%, #0f1b33);
    background: color-mix(in srgb, var(--blue) 88%, #0f1b33);
    font-size: 13.5px;
    box-shadow: 0 2px 8px rgba(32, 55, 84, 0.28);
  }
  .oga-stage-bar a:hover {
    background: color-mix(in srgb, var(--blue) 72%, #0f1b33);
    border-color: color-mix(in srgb, var(--blue) 72%, #0f1b33);
    box-shadow: 0 3px 10px rgba(32, 55, 84, 0.32);
  }
  .oga-stage-bar a svg {
    width: 16px;
    height: 16px;
  }

  .oga-frame-wrap, #chartFrame { min-height: 360px; }
  .oga-footnote {
    padding-inline: 0;
    margin-top: 0;
  }
}

@media (max-width: 460px) {
  .oga-portal { padding-inline: 12px; }
  .oga-header { gap: 9px; padding-top: 6px; }
  .oga-brand { align-items: flex-start; gap: 10px; }
  .oga-brand-mark { display: none; }
  .oga-brand-mark svg { width: 21px; height: 21px; }
  .oga-brand h1 { font-size: 22px; line-height: 1.08; }
  .oga-brand p { font-size: 11px; }
  .oga-stage-bar { align-items: center; justify-content: flex-end; }
  .oga-stage-bar--nudge { justify-content: flex-start; }
  .oga-stage-current { display: none; }
  .oga-stage-label { display: none; }
  .oga-stage-bar a { margin-top: 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation-duration: 1ms !important; }
}
